  function esc(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function clamp(value, min, max) { return Math.max(min, Math.min(max, Number(value) || 0)); }
  function gid(prefix) { return global.CBIData.createId(prefix || 'shop'); }
  function projects() { return db.work.shop.projects || []; }
  function projectById(id) { return projects().find(function (project) { return project.id === id; }) || null; }
  function itemById(project, id) { return project && project.items.find(function (item) { return item.id === id; }) || null; }
  function isOwned(id) { return db.work.shop.owned.indexOf(id) >= 0; }
  function walletDb() { try { return JSON.parse(global.localStorage.getItem('wallet_db')) || {}; } catch (error) { return {}; } }
  function availableFund() { return global.CBIData.availableShopFund(db, walletDb()); }
  function save() { db = global.CBIData.save(db) || db; }
  function projectColor() { return '#E8B96A'; }
  function personById(id) { return PERSON_PRESETS.find(function (person) { return person.type === id; }) || null; }
  function itemTargetId(item) { return item && Array.isArray(item.targetIds) && personById(item.targetIds[0]) ? item.targetIds[0] : ''; }
  function itemTargetName(item) { var person = personById(itemTargetId(item)); return person ? person.name : ''; }
  function itemTargetColor(item) { var person = personById(itemTargetId(item)); return person ? person.color : '#E8B96A'; }
  function projectCollapseKey(id) { return 'project:' + id; }
  function isProjectCollapsed(id) { return collapsed[projectCollapseKey(id)] === true; }
  function today() { return new Date().toISOString().slice(0, 10); }
  function loadCollapsed() {
    var defaults = { daily: false, special: true, major: true };
    try { var value = JSON.parse(global.localStorage.getItem(COLLAPSE_KEY) || '{}'); return value && typeof value === 'object' ? Object.assign(defaults, value) : defaults; }
    catch (error) { return defaults; }
  }
  function saveCollapsed() { try { global.localStorage.setItem(COLLAPSE_KEY, JSON.stringify(collapsed)); } catch (error) {} }

